import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`pricing-strategy`,heroTitle:`Build your pricing strategy in minutes`,heroSubtitle:`Perplexity Computer analyzes your services, researches competitor pricing, and builds a three-tier package structure — automatically.`,inputUrlCta:`Build my pricing`,inputUrlPlaceholder:`yourbusiness.com`,inputUrlPrefill:`Go to {url} and build a complete pricing strategy for this business. 1) Analyze the site's services, positioning, target audience, and any visible pricing. 2) Research 8-10 competitors in the same space — document what they charge for similar offerings, how they package their services, and where they anchor their pricing. 3) Identify where the business is leaving money on the table — underpriced services, missing upsells, no tiered structure, weak anchoring. 4) Build a three-tier package structure (Good / Better / Best) using anchor pricing psychology — name each tier, set exact price points, and define what's included in each. 5) Write compelling package descriptions that justify the price and push buyers toward the middle or top tier. 6) Draft a complete pricing page with FAQ objection-handlers addressing the top 6-8 concerns prospects have before buying. 7) Deliver everything in a full pricing strategy document: competitive landscape summary, pricing rationale, exact numbers for each tier, package breakdown with descriptions, and the client-ready pricing page copy you can publish immediately.`,heroOverlaySteps:[`Analyzing your services, positioning, and current pricing`,`Researching competitor pricing and package structures in your space`,`Building three-tier packages with anchor pricing psychology`,`Pricing strategy, package copy, and client-ready pricing page — ready to publish`],generatingSteps:[`Visiting {url} to extract your services, positioning, and visible pricing`,`Designing an agent to research competitor pricing and package structures across your market`,`Configuring tier architecture, anchor pricing logic, and objection-handling FAQ generation`,`Setting up your deliverable with exact price points, package copy, and a publishable pricing page`],featureSectionTitle:`From URL to pricing strategy`,featureCardTitles:[`Connects to your business stack`,`Outputs you can publish`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Docs, Notion, Stripe, QuickBooks — Computer plugs into your tools so pricing research and package building happen in one workflow.`,`Competitive pricing analysis. Three-tier package structure with exact numbers. Named tiers with descriptions. Pricing page copy with FAQ objection-handlers. A full strategy document ready for your team or your website.`],capabilitySectionTitle:`Your pricing strategist, on autopilot`,capabilitySectionSubtitle:`Paste your URL, step away, come back to a complete pricing strategy with exact numbers.`,capabilityCards:[{title:`Service Analysis`,description:`Computer can analyze your site's services, positioning, and current pricing — and identify exactly where you're leaving money on the table.`},{title:`Competitor Research`,description:`Computer can research 8-10 competitors in your space — documenting their pricing, packages, and positioning so you know exactly where the market sits.`},{title:`Package Architecture`,description:`Computer can build a three-tier package structure using anchor pricing psychology — with named tiers, exact price points, and compelling descriptions that push buyers up.`},{title:`Connect Your Tools`,description:`Computer can write to Google Sheets, Google Docs, Notion, and Stripe — so your pricing strategy flows from research to implementation in one place.`},{title:`Remember & Refine`,description:`Computer can remember your services, competitors, and past pricing decisions across sessions — so every revision builds on what's already working.`},{title:`Monitor & Alert`,description:`Computer can track competitor pricing changes monthly and alert you when the market shifts — so your packages stay competitive.`}]});export{t as default};
